CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260415214906_AddInternalPnr') THEN
    CREATE TABLE "Airlines" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(3) NOT NULL,
        "NameTr" character varying(100) NOT NULL,
        "NameEn" character varying(100) NOT NULL,
        "LogoUrl" character varying(255),
        "CountryCode" character varying(2),
        "Alliance" character varying(50),
        "IsDomestic" boolean NOT NULL,
        "IsActive" boolean NOT NULL,
        "SortOrder" integer NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        "UpdatedAt" timestamp without time zone,
        CONSTRAINT "PK_Airlines" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
