DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260415214906_AddInternalPnr') THEN
    CREATE TABLE "Bookings" (
        "Id" uuid NOT NULL,
        "UserId" uuid,
        "BiletBankFileId" uuid,
        "PNR" text,
        "InternalPnr" text,
        "Status" text NOT NULL,
        "GrandTotal" numeric,
        "Currency" text,
        "IsFinalized" boolean NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        "UpdatedAt" timestamp without time zone NOT NULL,
        "TransactionId" character varying(100),
        "Origin" character varying(3),
        "Destination" character varying(3),
        "AirlineCode" character varying(3),
        "FlightNumber" character varying(20),
        "SessionId" character varying(100),
        "SessionToken" character varying(100),
        "ProductItemId" character varying(100),
        "ServiceFee" numeric(18,2) NOT NULL,
        "OurCommission" numeric(18,2) NOT NULL,
        "AllocatedAt" timestamp without time zone,
        "BookedAt" timestamp without time zone,
        "PaidAt" timestamp without time zone,
        "TicketedAt" timestamp without time zone,
        "CancelledAt" timestamp without time zone,
        "LastError" text,
        "RetryCount" integer NOT NULL,
        "AdultCount" integer NOT NULL,
        "ChildCount" integer NOT NULL,
        "InfantCount" integer NOT NULL,
        "GuestSessionId" uuid,
        CONSTRAINT "PK_Bookings" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Bookings_GuestSessions_GuestSessionId" FOREIGN KEY ("GuestSessionId") REFERENCES "GuestSessions" ("Id"),
        CONSTRAINT "FK_Bookings_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
    );
    END IF;
END $EF$;

