DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260415214906_AddInternalPnr') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Airlines"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Airlines") + 1,
            nextval(pg_get_serial_sequence('"Airlines"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"FareTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "FareTypes") + 1,
            nextval(pg_get_serial_sequence('"FareTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"PopularRoutes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "PopularRoutes") + 1,
            nextval(pg_get_serial_sequence('"PopularRoutes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"BookingClasses"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "BookingClasses") + 1,
            nextval(pg_get_serial_sequence('"BookingClasses"', 'Id'))),
        false);
    END IF;
END $EF$;

