        "Id" uuid NOT NULL,
        "AdminUserId" uuid,
        "Username" character varying(64),
        "Action" character varying(128) NOT NULL,
        "TargetEntity" character varying(64),
        "TargetId" character varying(64),
        "Details" text,
        "Success" boolean NOT NULL,
        "ErrorMessage" character varying(1024),
        "IpAddress" character varying(64),
        "UserAgent" character varying(512),
        "CreatedAt" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_AdminAuditLogs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AdminAuditLogs_AdminUsers_AdminUserId" FOREIGN KEY ("AdminUserId") REFERENCES "AdminUsers" ("Id") ON DELETE SET NULL
    );
