DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260422113542_AddSupportTicketSystem') THEN
    CREATE TABLE "SupportTickets" (
        "Id" uuid NOT NULL,
        "TicketNumber" character varying(32) NOT NULL,
        "UserId" uuid NOT NULL,
        "BookingId" uuid,
        "Type" integer NOT NULL,
        "Subject" character varying(200) NOT NULL,
        "Status" integer NOT NULL,
        "ClosedAt" timestamp without time zone,
        "ClosedByAdminId" uuid,
        "LastActivityAt" timestamp without time zone NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        "UpdatedAt" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_SupportTickets" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_SupportTickets_AdminUsers_ClosedByAdminId" FOREIGN KEY ("ClosedByAdminId") REFERENCES "AdminUsers" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_SupportTickets_Bookings_BookingId" FOREIGN KEY ("BookingId") REFERENCES "Bookings" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_SupportTickets_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260422113542_AddSupportTicketSystem') THEN
    CREATE TABLE "SupportTicketMessages" (
        "Id" uuid NOT NULL,
        "TicketId" uuid NOT NULL,
        "SenderType" integer NOT NULL,
        "SenderId" uuid NOT NULL,
        "SenderDisplayName" character varying(128) NOT NULL,
        "Body" text NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_SupportTicketMessages" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_SupportTicketMessages_SupportTickets_TicketId" FOREIGN KEY ("TicketId") REFERENCES "SupportTickets" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

